'use client'
import { cn, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { forwardRef } from 'react'
import type { AnchorHTMLAttributes, HTMLAttributes } from 'react'
import styles from './skip-nav.module.css'

const DEFAULT_TARGET_ID = 'cascade-skip-target'

export interface SkipNavLinkProps extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'href'> {
  /**
   * SkipNavLink: id of the SkipNavTarget to jump to
   *
   * @defaultValue `cascade-skip-target`
   * @see the component manifest
   */
  targetId?: string
  labels?: { label?: string }
}

/** Render as the FIRST focusable element on the page — visually hidden until focused. */
/**
 * `forwardRef` so `ref` reaches the underlying `<a>` — and so it is TYPED. See
 * `textarea.tsx` for the full rationale (2026-07-28 report C10). Enforced by
 * `ref-parity.test.ts`, which found this component: the plan's own list of 16 was itself
 * incomplete, which is why the rule is a guard and not a checklist.
 */
export const SkipNavLink = forwardRef<HTMLAnchorElement, SkipNavLinkProps>(function SkipNavLink(
  { targetId = DEFAULT_TARGET_ID, labels, className, ...props },
  ref,
) {
  useSignals()
  const label = labels?.label ?? t(builtin.skipNav.label)
  return (
    <a ref={ref} href={`#${targetId}`} className={cn(styles['link'], className)} {...props}>
      {label}
    </a>
  )
})

export interface SkipNavTargetProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * SkipNavTarget: anchor id — must match the link targetId
   *
   * @defaultValue `cascade-skip-target`
   * @see the component manifest
   */
  id?: string
}

/** Place where the main content starts; the link's hash navigation moves focus here. */
export function SkipNavTarget({ id = DEFAULT_TARGET_ID, ...props }: SkipNavTargetProps) {
  return <div id={id} tabIndex={-1} {...props} />
}

@layer cascivo.component {
  .link {
    position: fixed;
    inset-block-start: var(--cascivo-space-2);
    inset-inline-start: var(--cascivo-space-2);
    z-index: 100;
    padding: var(--cascivo-space-2) var(--cascivo-space-3);
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);
    color: var(--cascivo-color-text);
    text-decoration: none;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    /* Visually hidden until focused */
    clip-path: inset(50%);

    &:focus-visible {
      clip-path: none;
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'SkipNav',
  // Compound module: no single `SkipNav` export — ships a link + its target.
  importSymbols: 'SkipNavLink, SkipNavTarget',
  description: 'Skip link that jumps keyboard users past the navigation to the main content',
  category: 'navigation',
  clientJs: 'enhancement',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'targetId',
      type: 'string',
      required: false,
      default: 'cascade-skip-target',
      description: 'SkipNavLink: id of the SkipNavTarget to jump to',
    },
    {
      name: 'labels',
      type: '{ label?: string }',
      required: false,
      description: 'SkipNavLink: overrides the built-in i18n label per instance',
    },
    {
      name: 'id',
      type: 'string',
      required: false,
      default: 'cascade-skip-target',
      description: 'SkipNavTarget: anchor id — must match the link targetId',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-text',
    '--cascivo-radius-control',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'link',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter'],
  },
  examples: [
    {
      title: 'Default pair',
      code: '<><SkipNavLink /><nav>…</nav><SkipNavTarget /><main>…</main></>',
      description: 'SkipNavLink must be the first focusable element on the page',
    },
    {
      title: 'Custom target',
      code: '<><SkipNavLink targetId="main-content" /><SkipNavTarget id="main-content" /></>',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['accessibility', 'skip-link', 'keyboard', 'navigation'],
  intent: {
    whenToUse: [
      'Letting keyboard users jump past repeated navigation to the main content',
      'Meeting WCAG bypass-blocks by providing a skip link as the first focusable element',
      'Targeting a custom main-content anchor (targetId / matching SkipNavTarget id)',
    ],
    whenNotToUse: [
      'General in-page navigation — use anchor links or a table of contents',
      'Visible persistent navigation — this link is hidden until focused',
    ],
    antiPatterns: [
      {
        bad: 'Placing SkipNavLink after the navigation in the DOM',
        good: 'Make SkipNavLink the first focusable element on the page',
        why: 'A skip link only works if the user reaches it before tabbing through the nav it bypasses',
      },
    ],
    related: [
      {
        name: 'ShellHeader',
        relationship: 'alternative',
        reason: 'ShellHeader has a built-in skip-to-content link for console shells',
      },
    ],
    a11yRationale:
      'Renders an anchor that is visually hidden until focused, then becomes visible so sighted keyboard users see where focus is; activating it moves focus to the matching target past the navigation',
    content: {
      tone: 'Plain instruction ("Skip to content")',
      notes: 'Label is i18n-driven and overridable per instance',
    },
    flexibility: [
      {
        area: 'target id',
        level: 'flexible',
        note: 'targetId/id may be customized as long as they match',
      },
      {
        area: 'first-focusable placement',
        level: 'strict',
        note: 'SkipNavLink must be the first focusable element to function',
      },
    ],
  },
}
